Now compute missing qualifications per applicant and count those missing exactly one.
Logic:
- Degree must be Masters or PhD AND field in {Biology, Biochemistry, Biotechnology}
- Experience >= 3
- Lab Trained == 'Y'
- Publications >= 3
- Citizen == 'Y'
- Programming Lang in {C++, C#, Fortran}
- Second Language present (non-empty)
Python code to run:
import pandas as pd
ap = './jobpack/Applicants.xlsx'
df = pd.read_excel(ap)
valid_fields = {'Biology','Biochemistry','Biotechnology'}
valid_langs = {'C++','C#','Fortran'}

def missing_count(row):
    m = 0
    if row['Degree Level'] not in {'Masters','PhD'} or row['Degree Field'] not in valid_fields:
        m += 1
    if pd.isna(row['Experience (Years)']) or row['Experience (Years)'] < 3:
        m += 1
    if str(row['Lab Trained (Y/N)']).strip().upper() != 'Y':
        m += 1
    if pd.isna(row['Publications']) or row['Publications'] < 3:
        m += 1
    if str(row['Citizen (Y/N)']).strip().upper() != 'Y':
        m += 1
    if str(row['Programming Lang']).strip() not in valid_langs:
        m += 1
    if pd.isna(row['Second Language']) or str(row['Second Language']).strip() == '':
        m += 1
    return m

df['Missing'] = df.apply(missing_count, axis=1)
count_exactly_one = int((df['Missing'] == 1).sum())
print('Number of applicants missing exactly one qualification:', count_exactly_one)

